const int MAX_SIZE=2000005;
int edge_count, nexts[MAX_SIZE], head_list[MAX_SIZE], target[MAX_SIZE], capacity[MAX_SIZE], dist_array[MAX_SIZE], start_node, end_node, total_nodes, total_edges, x_vals[MAX_SIZE], y_vals[MAX_SIZE], visited_flags[MAX_SIZE], weights[MAX_SIZE], current_edge[MAX_SIZE], k_param, c_param, d_param;
queue<int> q;
void add_link(int u, int v, int cap, int wght){
    nexts[++edge_count]=head_list[u];
    head_list[u]=edge_count;
    target[edge_count]=v;
    capacity[edge_count]=cap;
    weights[edge_count]=wght;
    nexts[++edge_count]=head_list[v];
    head_list[v]=edge_count;
    target[edge_count]=u;
    capacity[edge_count]=0;
    weights[edge_count]=-wght;
}
int spfa(){
    q.push(start_node);
    memset(dist_array,0x3f,sizeof dist_array);
    dist_array[start_node]=0;
    while (!q.empty()){
        int u=q.front();q.pop();visited_flags[u]=0;
        for (int i=head_list[u];i;i=nexts[i])
            if (capacity[i]&&dist_array[target[i]]>dist_array[u]+weights[i]){
                dist_array[target[i]]=dist_array[u]+weights[i];
                if (!visited_flags[target[i]]){
                    visited_flags[target[i]]=1;
                    q.push(target[i]);
                }
            }
    }
    return dist_array[end_node]<=1e9;
}
int dfs(int u,int flow_in){
    int total_flow=0,flow_bottle;
    visited_flags[u]=1;
    if (u==end_node)return flow_in;
    for (int &i=current_edge[u];i;i=nexts[i])
        if (!visited_flags[target[i]]&&capacity[i]&&dist_array[target[i]]==dist_array[u]+weights[i]&&(flow_bottle=min(flow_in,dfs(target[i],min(flow_in,capacity[i]))))){
            capacity[i]-=flow_bottle;
            capacity[i^1]+=flow_bottle;
            total_flow+=flow_bottle;flow_in-=flow_bottle;
            if (!flow_in)return total_flow;
        }
    return total_flow;	
}
int main(){
    scanf("%d%d%d%d%d",&total_nodes,&total_edges,&k_param,&c_param,&d_param);
    start_node=0; end_node=1;
    edge_count=1;
    for (int i=1;i<=k_param;i++){
